import 'dart:convert';

import 'package:genui/genui.dart';

import 'genui_catalog.g.dart';

/// The catalog the playground renders: the components generated by genui_gen
/// plus genui's basic ones, which the generated examples rely on.
final Catalog playgroundCatalog = genUiCatalog.copyWith(
  newItems: BasicCatalogItems.asCatalog().items.toList(),
  newFunctions: BasicCatalogItems.asCatalog().functions.toList(),
);

/// The id surfaces use to name [playgroundCatalog].
String get playgroundCatalogId => playgroundCatalog.catalogId!;

/// The names of the playground's own components.
abstract final class PlaygroundComponents {
  static const alertBanner = 'AlertBannerWidget';
  static const attachmentList = 'AttachmentListWidget';
  static const customButton = 'CustomButton';
  static const metricChart = 'MetricChartWidget';
  static const priorityPill = 'PriorityPillWidget';
  static const productCard = 'ProductCardWidget';
  static const quickReplies = 'QuickRepliesWidget';
  static const singleAttachment = 'SingleAttachmentWidget';
  static const stats = 'StatsWidget';
  static const taskItem = 'TaskItemWidget';
  static const timeline = 'TimelineWidget';
  static const userCard = 'UserCardWidget';
}

/// The JSON schema of each of the playground's own components, by name.
Map<String, Map<String, dynamic>> get playgroundSchemas => {
  for (final item in genUiCatalogItems)
    item.name: jsonDecode(item.dataSchema.toJson()) as Map<String, dynamic>,
};

/// The playground's own components described for a system prompt: the
/// schema of each one and the example genui_gen generated for it.
String get playgroundComponentsPromptDescription {
  final buffer = StringBuffer();
  for (final item in genUiCatalogItems) {
    buffer.writeln('- Component: "${item.name}"');
    buffer.writeln('  Schema: ${item.dataSchema.toJson()}');
    for (final example in item.exampleData) {
      buffer.writeln('  Example components: ${example()}');
    }
  }
  return buffer.toString();
}
